    },
    [29] = {
      beijing = 3860,
      dialog = 3,
      music = "46_Split_in_Black",
      renwu = "npc",
      sentence = "Doing my best to contain my shock, I thought of all the times in recent years when I heard that an anti-reformation aristocrat stepped down from public life or mysteriously died, and apparently...",
      next = {30}
    },
    [30] = {
      beijing = 3860,
      dialog = 3,
      music = "46_Split_in_Black",
      renwu = "npc",
      sentence = "...everyone, including myself, had greatly underestimated this \"dying\" king.",
