      music = "46_Split_in_Black",
      renwu = "npc",
      role1 = 1163000,
      role2 = 102102,
      role3 = 102201,
      role5 = 1163402,
      role6 = 11625007,
      sentence = "Almost at the same moment that I registered this with my eyes, the reek of blood and rust also hit my nose. I covered my mouth and nose reflexively and clutched at my sleeve hem.",
