      role1 = 1163000,
      role2 = 102102,
      role3 = 102201,
      role5 = 1163402,
      role6 = 11625007,
      sentence = "But those people are more cautious than rats at nightfall, so all we found was this evidence. We're still searching for the bodily remains from the blood sacrifices.",
