      renwu = "npc",
      role1 = 233000,
      role2 = 201106,
      role3 = 201201,
      role5 = 233404,
      ruchang = -1,
      sentence = "I subconsciously looked at Lucien. Maybe because of the scorching sun at noon, he had a thin layer of sweat over the corners of his brow.",
